use xiom.io;

type Resource = {
  data: Int;
  active: Bool;
  invariant: active == true;
}

fn process_resource(r: &mut Resource)
  requires: r.active;
{
  r.data = r.data * 2;
}

fn consume_resource(r: Resource) -> Int {
  return r.data;
}

fn main() -> Int {
  var res: Resource = Resource{ data: 21, active: true };
  process_resource(&mut res);
  let value = consume_resource(res);
  return value;
}
